  setGradeGrace(id: string, grade: Grade, days: number | null, from: string | null): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/settings/grace/${grade}`, { days, from })
      .pipe(tap((s) => this.active.set(s)));
  }

